<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\SoftDeletes;
class ProspectingJob extends Model { use SoftDeletes; protected $fillable=['user_id','lead_list_id','scraper_job_id','keywords','location','latitude','longitude','search_parameters','status','progress','scraper_slot_acquired','polling_claimed_at','polling_claim_token','submission_intent_at','submission_attempt_token','cancel_requested_at','error_message','started_at','finished_at']; protected $casts=['keywords'=>'array','search_parameters'=>'array','started_at'=>'datetime','finished_at'=>'datetime','polling_claimed_at'=>'datetime','submission_intent_at'=>'datetime','cancel_requested_at'=>'datetime','scraper_slot_acquired'=>'boolean']; public function user(){return $this->belongsTo(User::class);} public function leadList(){return $this->belongsTo(LeadList::class,'lead_list_id');} public function leads(){return $this->hasMany(Lead::class);} public function attempts(){return $this->hasMany(ProspectingJobAttempt::class);} }
